using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class MilitaryAuthorityKnowledgeTests
{
 static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
 static void Send(WorldSession s,NewMilitaryAction a){var i=new NewMilitaryInput(new("request:authority-known/"+s.Revision+"/"+a),a){AuthorityPolicy=a==NewMilitaryAction.Request?NewGameMilitary.AuthorityContract:null};var r=s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
 static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
 static WorldSession Accept(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Send(s,NewMilitaryAction.Request);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);return s;}
 [Fact]public void UnknownPermissionSourceCannotChangePlayerAuthorityLabel(){var s=Accept();string before=NewGameMilitary.AuthorityKnownStatus(s.DiagnosticSnapshot());At(s,3);Assert.Equal(2,s.DiagnosticSnapshot().NewMilitary!.Authority!.Proofs.Length);Assert.Equal(before,NewGameMilitary.AuthorityKnownStatus(s.DiagnosticSnapshot()));At(s,4);Assert.Equal(before,NewGameMilitary.AuthorityKnownStatus(s.DiagnosticSnapshot()));Open(s);Assert.Contains("現地引受前",NewGameMilitary.AuthorityKnownStatus(s.DiagnosticSnapshot()));Send(s,NewMilitaryAction.Pickup);var label=NewGameMilitary.AuthorityKnownStatus(s.DiagnosticSnapshot());Assert.Contains("兵・兵糧の所有",label);Assert.DoesNotContain("office:",label);}
 [Fact]public void UnknownReturnDoesNotCloseVisibleAuthorityBeforeActualNoticeIsOpened(){var s=Accept();At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Report);At(s,5);Send(s,NewMilitaryAction.Return);string before=NewGameMilitary.AuthorityKnownStatus(s.DiagnosticSnapshot());At(s,6);Assert.NotNull(s.DiagnosticSnapshot().NewMilitary!.Authority!.Grants.Single().UntilRevision);Assert.Equal(before,NewGameMilitary.AuthorityKnownStatus(s.DiagnosticSnapshot()));At(s,7);Assert.Equal(before,NewGameMilitary.AuthorityKnownStatus(s.DiagnosticSnapshot()));Open(s);Assert.Contains("指揮返還を確認",NewGameMilitary.AuthorityKnownStatus(s.DiagnosticSnapshot()));}
 [Fact]public void LegacyLoanDoesNotAcquireAuthorityLabel(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(new(new("request:legacy-visible"),NewMilitaryAction.Request),s.PlayerControl,s.Revision).Code);At(s,2);Open(s);Assert.Equal("",NewGameMilitary.AuthorityKnownStatus(s.DiagnosticSnapshot()));}
}
